template <class F, class G>
auto and_then(F f, G g) {
  return [f, g](auto&& x) { return g(f(std::forward<decltype(x)>(x))); };
}
auto f = and_then([](int x) { return x + 1; }, [](int x) { return x * 2; });
std::function<int(int)> erased = f;   // only when type erasure is required
// f(3) == 8

